import{n as e}from"./createLucideIcon-DLmAVpDi.js";import{W as t,u as n}from"./index-CCOe1rrM.js";import{t as r}from"./PdfPageWorkspace-BC4xbP_V.js";var i=e(),a=n(`rotate-pdf`),o={intro:`Rotate PDF fixes pages that are sideways or upside down. Every page renders as a thumbnail with its own rotate button — click it to cycle that page 90° at a time, then export the corrected document, all in your browser.`,whyItMatters:`Scanned documents are often rotated incorrectly depending on how the page was fed through a scanner or photographed, and it’s common for only some pages to be affected. Fixing orientation page-by-page before sharing or submitting makes the document actually readable without forcing every page through the same rotation.`,howItWorks:[`Select a PDF file — every page renders as a thumbnail in a grid.`,`Click the rotate button in the corner of a page to turn it 90° clockwise; click it again to reach 180°, again for 270°, and a fourth time to return to the original orientation.`,`Rotate as many or as few pages as you need — there’s no single "rotate whole document" switch, so if every page needs the same fix, click each page’s rotate button the same number of times.`,`Click "Apply rotation" to generate the corrected document, then download it.`],examples:[{title:`Fixing a scanned document`,body:`Rotate every page 90° clockwise (one click each) when a whole document was scanned sideways, so it reads normally without tilting your screen.`},{title:`Fixing one sideways page`,body:`In an otherwise correctly-scanned document, click the rotate button on just the one page that came out sideways, leaving the rest untouched.`}],mistakes:[`Assuming there’s a bulk "rotate whole document" option — there isn’t; rotation is applied per page via each thumbnail’s own rotate button, so a full-document fix means clicking through every page.`,`Clicking the rotate button one time too many — each click adds 90° and wraps back to 0° after four clicks, so it’s easy to overshoot past the angle you wanted.`],tips:[`Check each page after rotating a mixed-orientation scan — different pages may need a different number of clicks, since rotation is set independently per page.`,`The thumbnail preview updates immediately as you click, so you can confirm the orientation looks right before applying the rotation to the whole document.`],faqs:[{question:`Can I rotate just one page in a multi-page PDF?`,answer:`Yes — rotation is applied per page by default; click a specific page’s rotate button and leave the rest alone.`},{question:`Does rotating affect the PDF’s text or quality?`,answer:`No — rotation only changes page orientation metadata; the page content itself is untouched.`},{question:`How do I rotate a page 180° or 270°?`,answer:`Click the rotate button multiple times — each click adds 90°, so two clicks gives 180° and three clicks gives 270°. A fourth click returns the page to its original orientation.`},{question:`Is there a way to rotate every page at once?`,answer:`Not as a single switch — you click each page’s rotate button individually, which does mean more clicks for a full-document rotation but allows different pages to end up at different angles.`}],related:[{label:`Rearrange Pages`,href:`/document-tools/rearrange-pdf`},{label:`Delete Pages`,href:`/document-tools/delete-pdf-pages`}]};function s(){return(0,i.jsx)(r,{mode:`rotate`,toolName:a.name,tagline:a.tagline,description:a.description,path:`/document-tools/rotate-pdf`,icon:t,breadcrumb:{label:`Rotate PDF`},toolSlug:a.slug,article:o})}export{s as default};